"""Reusable commercial offer; one tax-inclusive total shared by all sales pages."""
from urllib.parse import quote
from build import t

OFFER_TOTAL = '997.99'


def enquiry_link():
    es = f'Hola, me interesa la experiencia inmobiliaria 3D de US${OFFER_TOTAL}, IVA incluido.\n\nProyecto:\nCiudad:\nNúmero de unidades y tipologías:\nPlanos o modelos disponibles:\nFecha estimada de lanzamiento:\n\nQuisiera revisar el alcance y recibir una proforma personalizada.'
    en = f'Hello, I am interested in the 3D real estate experience for US${OFFER_TOTAL}, including VAT.\n\nProject:\nCity:\nNumber of units and apartment types:\nAvailable plans or models:\nTarget launch date:\n\nI would like to review the scope and receive a personalised proforma.'
    base = 'mailto:alvaroipazr@gmail.com?subject=' + quote('Proforma · Experiencia inmobiliaria 3D') + '&body='
    return f'<a class="button offer-enquiry" href="{base + quote(es)}" data-mail-es="{base + quote(es)}" data-mail-en="{base + quote(en)}">{t("Quiero esta experiencia ↗", "I want this experience ↗")}</a>'


def offer(show_intro=True):
    rows = [
        ('01', 'Tu marca, tu proyecto', 'Your brand, your project', 'Sitio web adaptado a la identidad de un proyecto inmobiliario, con presentación comercial en español e inglés.', 'A website tailored to one real estate project’s identity, with a commercial presentation in Spanish and English.'),
        ('02', 'Arquitectura que se explora', 'Architecture to explore', 'Vista exterior 3D interactiva, puntos de interés y cambios de iluminación, tomando esta demo como base.', 'An interactive 3D exterior, points of interest and lighting changes, using this demo as the starting point.'),
        ('03', 'Cada vivienda, en contexto', 'Every home in context', 'Selector por piso, tipología y disponibilidad, con superficie y datos de la vivienda seleccionada.', 'Selection by floor, apartment type and availability, with area and details of the selected home.'),
        ('04', 'Interiores por tipología', 'Interiors by apartment type', 'Recorrido de espacios con distribuciones diferenciadas y navegación por ambientes según las tipologías acordadas.', 'A room-by-room journey with distinct layouts and navigation for the agreed apartment types.'),
        ('05', 'Una consulta mejor preparada', 'A better-informed enquiry', 'Contacto comercial con los datos de la unidad elegida para que tu equipo pueda continuar la conversación.', 'A sales enquiry carrying the selected unit’s details, so your team can continue the conversation.'),
        ('06', 'Listo para compartir', 'Ready to share', 'Adaptación a móvil y escritorio, revisión del recorrido y publicación en el dominio acordado.', 'Mobile and desktop layouts, journey review and publication on the agreed domain.'),
    ]
    scope = ''.join(f'<li><span class="scope-number">{n}</span><div><h3>{t(es,en)}</h3><p>{t(desc,desc_en)}</p></div><span class="scope-check" aria-hidden="true">✓</span></li>' for n,es,en,desc,desc_en in rows)
    heading = f'''<div class="offer-heading"><span class="eyebrow">{t('UNA PROPUESTA. TODA LA EXPERIENCIA.', 'ONE OFFER. THE COMPLETE EXPERIENCE.')}</span><h2 id="offer-heading">{t('De la primera mirada<br>a la <em>consulta comercial.</em>', 'From the first look<br>to the <em>sales enquiry.</em>')}</h2><p>{t('Adaptamos esta experiencia a tu proyecto para que tus compradores puedan explorar, elegir y llegar a tu equipo con una vivienda en mente.', 'We adapt this experience to your project so buyers can explore, choose and reach your team with a home in mind.')}</p></div>'''
    return f'''<section class="offer-section" id="inversion" aria-label="Propuesta e inversión / Offer and investment">
{heading if show_intro else ''}
      <div class="offer-grid"><div class="offer-scope"><h3 class="scope-heading">{t('Lo que recibe tu proyecto', 'What your project receives')}</h3><ol>{scope}</ol></div>
      <aside class="investment" aria-label="Inversión / Investment"><span class="eyebrow">{t('EXPERIENCIA INMOBILIARIA 3D', '3D REAL ESTATE EXPERIENCE')}</span><div class="offer-price"><span>US$</span><strong>{OFFER_TOTAL}</strong></div><p class="tax-note">{t('Precio total · IVA incluido', 'Total price · VAT included')}</p><div class="investment-rule"></div><p class="offer-definition">{t('Una implementación.<br>Un proyecto inmobiliario.<br>Una experiencia completa.', 'One implementation.<br>One real estate project.<br>One complete experience.')}</p>{enquiry_link()}<a class="offer-demo" href="/proyecto/">{t('Explorar la demo antes de decidir', 'Explore the demo before deciding')} →</a><p class="investment-note">{t('El correo se abre con el precio y los datos que necesitamos. Puedes revisarlo antes de enviarlo.', 'Your email opens with the price and the details we need. You can review it before sending.')}</p></aside></div>
      <div class="offer-process"><div><span class="eyebrow">{t('ASÍ LO LLEVAMOS A TU PROYECTO', 'HOW WE BRING IT TO YOUR PROJECT')}</span><h2>{t('Tres pasos.<br> <em>Un mismo objetivo.</em>', 'Three steps.<br> <em>One shared goal.</em>')}</h2></div><ol><li><b>01 / {t('Definimos', 'Define')}</b><p>{t('Revisamos marca, planos, inventario y materiales 3D. Acordamos el alcance, las fechas y la forma de pago.', 'We review your brand, plans, inventory and 3D materials, then agree on scope, dates and payment terms.')}</p></li><li><b>02 / {t('Adaptamos', 'Adapt')}</b><p>{t('Preparamos el sitio y el recorrido. Tu equipo valida los espacios, la información y los contactos.', 'We prepare the site and tour. Your team validates the spaces, information and contacts.')}</p></li><li><b>03 / {t('Publicamos', 'Publish')}</b><p>{t('Revisamos la experiencia en móvil y escritorio y dejamos listo el enlace para tus campañas y asesores.', 'We review the mobile and desktop experience and prepare the link for your campaigns and sales team.')}</p></li></ol></div>
      <div class="offer-notes"><div><h3>{t('Para preparar tu proyecto', 'To prepare your project')}</h3><p>{t('Necesitamos tu marca, planos o modelos disponibles, tipologías, inventario y contactos comerciales. El detalle y la fidelidad de los espacios 3D se acuerdan al revisar estos materiales.', 'We need your brand, available plans or models, apartment types, inventory and sales contacts. The detail and fidelity of the 3D spaces are agreed when reviewing these materials.')}</p></div><div><h3>{t('Alcance y condiciones', 'Scope and terms')}</h3><p>{t('El total corresponde a la implementación descrita para un proyecto. Dominio, hosting, licencias de terceros e integraciones externas se definen y cotizan por separado. Calendario, revisiones y forma de pago se confirman por escrito antes de iniciar.', 'The total covers the implementation described for one project. Domain, hosting, third-party licences and external integrations are scoped and quoted separately. Schedule, revisions and payment terms are confirmed in writing before starting.')}</p></div></div>
      <p class="offer-disclosure">{t('Residencia 01 es una demostración ficticia. La gestión y las conexiones externas mostradas en la demo son simulaciones. Esta proforma es una propuesta comercial y no una factura.', 'Residencia 01 is a fictional demonstration. Management and external connections shown in the demo are simulations. This proforma is a commercial proposal, not an invoice.')}</p>
    </section>'''


def proforma_body():
    return f'''<main id="main" class="commercial-proforma"><div class="proforma-masthead"><div><span class="eyebrow">ANDEAN SOFTWARE LAB / {t('PROPUESTA COMERCIAL', 'COMMERCIAL PROPOSAL')}</span><h1>{t('Tu próxima<br><em>herramienta de venta.</em>', 'Your next<br><em>sales tool.</em>')}</h1><p>{t('Sitio inmobiliario con recorrido 3D para un proyecto.', 'A real estate website with a 3D journey for one project.')}</p></div><div class="proforma-actions"><button class="button" id="print-proforma" type="button">{t('Imprimir / guardar PDF', 'Print / save PDF')} ↗</button><a class="text-button" href="/proyecto/">{t('Ver la experiencia 3D', 'See the 3D experience')} →</a></div></div>{offer(False)}<div class="proforma-contact"><b>ANDEAN SOFTWARE LAB</b><span>Alvaro Paz · alvaroipazr@gmail.com</span><span>Martín Vélez Falconí · martinvelezf@hotmail.com</span><a href="https://inmobiliaria.alvaropaz.com/proyecto/">inmobiliaria.alvaropaz.com</a></div></main>'''
